        const _entity1 = entity1 instanceof Entity ? entity1.handle() : entity1;
        const _entity2 = entity2 instanceof Entity ? entity2.handle() : entity2;
        AttachEntitiesToRope(ropeId, _entity1, _entity2, ent1X, ent1Y, ent1Z, ent2X, ent2Y, ent2Z, length, alwaysZero1, alwaysZero2, boneName1, boneName2, false, boneId1, boneId2, alwaysZero3, alwaysZero4, false, false);
